const preview=document.getElementById('document-preview'),previewBody=document.getElementById('preview-body');let previewVersion=0,previewBlob=null,previewUrl=null;

function closePreview(){previewVersion++;preview.close();previewBody.innerHTML='';if(previewBlob)URL.revokeObjectURL(previewBlob);previewBlob=null;}

const weeklyMenuPreviews=new Map();
function prepareWeeklyMenu(url){const u=new URL(url,location.origin);u.searchParams.set('format','model');u.searchParams.delete('download');u.searchParams.delete('engine');const key=interfaceRevision+':'+u.href;if(!weeklyMenuPreviews.has(key)){if(weeklyMenuPreviews.size>=4)weeklyMenuPreviews.delete(weeklyMenuPreviews.keys().next().value);const pending=Promise.all([fetch(u,{cache:'no-store'}).then(async r=>{if(!r.ok)throw Error('Le menu ne peut pas être chargé.');const model=await r.json();if(model.kind!=='weekly-menu')throw Error('Menu de la semaine attendu.');return model;}),ensureWeeklyMenuLayout()]).then(([model])=>PaperChefWeeklyMenu.html(model));weeklyMenuPreviews.set(key,pending);pending.catch(()=>weeklyMenuPreviews.delete(key));}return weeklyMenuPreviews.get(key);}
for(const eventName of ['pointerover','focusin'])document.addEventListener(eventName,e=>{const link=e.target.closest('.week-menu-title-link');if(link&&!link.contains(e.relatedTarget))prepareWeeklyMenu(link.href).catch(()=>{});});
async function openDocument(url,label,format){const version=++previewVersion;previewUrl=url;preview.classList.toggle('weekly-menu-preview',new URL(url,location.origin).pathname==='/documents/weekly-menu');const u=new URL(url,location.origin),webPreview=u.pathname.startsWith('/documents/');format=format||u.searchParams.get('format')||(webPreview?'html':'pdf');document.getElementById('preview-title').textContent=label;previewBody.innerHTML='<p role="status">Chargement avec les données actuelles…</p>';document.getElementById('preview-actions').hidden=true;if(previewBlob)URL.revokeObjectURL(previewBlob);previewBlob=null;if(!preview.open)preview.showModal();try{u.searchParams.set('format',format);previewUrl=u.href;const response=format==='html'&&u.pathname==='/documents/weekly-menu'?new Response(await prepareWeeklyMenu(u.href),{headers:{'Content-Type':'text/html; charset=utf-8'}}):format==='pdf'&&webPreview?new Response(await (await ensureClientPdf()).generate(u,message=>{if(version===previewVersion)previewBody.textContent=message;}),{headers:{'Content-Type':'application/pdf'}}):await fetch(u,{cache:'no-store'});if(!response.ok){let error;try{error=(await response.json()).error;}catch{}throw new Error(error||'La génération du document a échoué.');}const expected=format==='html'?'text/html':'application/pdf';if(!response.headers.get('content-type')?.includes(expected))throw new Error('Le document reçu est invalide.');const payload=format==='html'?await response.text():await response.blob();if(version!==previewVersion)return;previewBody.innerHTML='';const frame=document.createElement('iframe');frame.title=format==='html'?'Aperçu du document':'Aperçu PDF';if(format==='html')frame.srcdoc=payload;else{previewBlob=URL.createObjectURL(payload);frame.src=previewBlob;}previewBody.append(frame);const pdf=new URL(u);pdf.searchParams.set('format','pdf');pdf.searchParams.set('download','1');document.getElementById('preview-download').href=previewBlob||pdf.href;document.getElementById('preview-web').hidden=!webPreview;document.getElementById('preview-pdf').hidden=!webPreview;document.getElementById('preview-web').disabled=format==='html';document.getElementById('preview-pdf').disabled=format==='pdf';document.getElementById('preview-actions').hidden=false;document.dispatchEvent(new CustomEvent('document-action-complete',{detail:{mode:'view',url:u.href}}));}catch(error){if(version===previewVersion)previewBody.innerHTML=`<p role="alert">${esc(error.message)}</p><button type="button" class="button" id="preview-retry">Réessayer</button>`;}}

