// Même formulaire pour les entrées Bibliothèque, Semaine et gestion d’une occurrence.
async function addEditor(date,period,templateId){return planningEditor({action:'add',date,period,templateId});}
async function chooseSlot(templateId){try{await planningEditor({action:'add',templateId});}catch(error){notify(error.message);}}
async function planningEditor({action,planned,date,period,templateId}){
 if(planned&&action!=='copy'&&window.PaperChefShared?.status?.services.find(s=>s.id===planned.id)?.order.done)throw Error('Commande faite : rouvrez la commande avant de modifier ce service.');
 if(window.planningEditorBuilding)return;
 window.planningEditorBuilding=true;dialog.style.visibility='hidden';
 try{
  const [choices,pickerCatalog]=await Promise.all([api('/api/library'),api('/api/week-types/catalog')]),weekId=planned?.week_id||state.weekId,locked=['copy','move'].includes(action),fixed=action==='update'||(action==='add'&&!!date);
  const selected=templateId||planned?.service_template_id||'';
  if(!choices.length&&!planned)throw new Error('Ajoutez d’abord un service type à la bibliothèque.');
  if(planned&&!choices.some(t=>t.id===selected))choices.push({id:selected,name:'Service actuel (retiré)',referenceCovers:planned.cover_count});
  const day=state.week?.menu.days.find(d=>d.date===date),titles={add:(day?.dayLabel||'Ajouter un service')+' · '+(period==='dinner'?'Soir':'Midi'),update:'Modifier le service',copy:'Copier le service',move:'Déplacer le service'};
  const search=locked?'<p><strong>'+esc(choices.find(t=>t.id===selected)?.name||'Service actuel')+'</strong></p>':'<section data-service-mini-library></section>';

  showEditor(titles[action],search+'<label hidden>Service type<select name="serviceTemplateId" '+(locked?'disabled':'')+'><option value="">Choisir un service</option>'+choices.map(t=>'<option value="'+esc(t.id)+'" '+(t.id===selected?'selected':'')+'>'+esc(t.name)+'</option>').join('')+'</select></label><label '+(fixed?'hidden':'')+'>Semaine<select name="weekId">'+state.weeks.map(w=>'<option value="'+esc(w.id)+'" '+(w.id===weekId?'selected':'')+'>'+shortDate(w.start_date)+' – '+shortDate(w.end_date)+'</option>').join('')+'</select></label><div class="planning-fields" '+(fixed?'hidden':'')+'><label>Jour<select name="date"></select></label><label>Repas<select name="mealPeriod"><option value="lunch">Midi</option><option value="dinner">Soir</option></select></label></div><div class="mini-planning-effectifs"><label data-planned-split hidden>Répartition viande / poisson<select name="meatPercent" disabled><option value="70">70 % viande / 30 % poisson</option><option value="50">50 % viande / 50 % poisson</option><option value="30">30 % viande / 70 % poisson</option></select></label><label>Effectif<input name="coverCount" type="number" min="1" step="1" required value="'+(planned?.cover_count||choices.find(t=>t.id===selected)?.referenceCovers||100)+'"></label></div><div class="planning-recap" '+(fixed?'hidden':'')+' role="status" aria-label="Récapitulatif"></div>',{kind:'planning',action,planned,choices,selectionPending:!selected});
  const select=content.querySelector('[name=serviceTemplateId]'),ratio=content.querySelector('[data-planned-split]');ratio.querySelector('select').value=String(planned?.meat_percent??70);
  const refreshRatio=()=>{const chosen=choices.find(t=>t.id===select.value);ratio.hidden=state.editing.selectionPending||!chosen||chosen.portionMode!=='split'||!chosen.mainType?.includes('Viande')||!chosen.mainType?.includes('Poisson');ratio.querySelector('select').disabled=ratio.hidden;};
  select.addEventListener('change',refreshRatio);
  let miniPicker;
  if(!locked){const services=choices.map(t=>({...t,...pickerCatalog.services.find(s=>s.id===t.id),components:t.components,vegetarian:t.portionMode==='all'}));const currentEditing=state.editing;
   const blocked=()=>'';
   miniPicker=ServicePicker.mount(content.querySelector('[data-service-mini-library]'),{services,selected,reason:blocked,onSelect:(s,warning)=>{select.value=s.id;currentEditing.selectionPending=false;currentEditing.pickerException=warning;select.dispatchEvent(new Event('change',{bubbles:true}));}});currentEditing.miniPicker=miniPicker;
   dialog.classList.add('mini-library-editor');
  }
  await loadPlanningDestination(weekId,date||planned?.service_date,period||planned?.meal_period);
  if(action==='add'&&date&&(content.querySelector('[name=date]').value!==date||content.querySelector('[name=mealPeriod]').value!==period))throw new Error('Ce créneau vient d’être occupé. Actualisez le planning.');
  refreshRatio();form.querySelector('[type=submit]').textContent={add:'Ajouter ce service',update:'Enregistrer le changement',copy:'Copier',move:'Déplacer'}[action];
  miniPicker?.refresh();document.getElementById('editor-title').textContent='Choisir un service · '+(content.querySelector('[name=date]').selectedOptions[0]?.textContent||'')+' · '+(content.querySelector('[name=mealPeriod]').value==='lunch'?'Midi':'Soir');window.planningEditorBuilding=false;dialog.style.visibility='';if(!dialog.open)dialog.showModal();miniPicker?.focus();const scrollBody=dialog.querySelector('.dialog-scroll-body');if(scrollBody)scrollBody.scrollTop=0;
 }catch(error){dialog.style.visibility='';throw error;}finally{window.planningEditorBuilding=false;}
}

async function loadPlanningDestination(weekId,preferredDate,preferredPeriod){
 const editing=state.editing,requestId=(editing.destinationRequest||0)+1;editing.destinationRequest=requestId;editing.destinationLoading=true;form.querySelector('[type="submit"]').disabled=true;
 try{const destination=await api('/api/week?'+query({id:weekId}));if(state.editing!==editing||editing.destinationRequest!==requestId)return;editing.destination=destination;
 const field=content.querySelector('[name="date"]');field.innerHTML=destination.menu.days.map(d=>'<option value="'+d.date+'">'+esc(d.dayLabel)+' '+shortDate(d.date)+'</option>').join('');
 const available=(d,p)=>!d[p==='lunch'?'lunchService':'dinnerService']||(editing.action!=='copy'&&d[p==='lunch'?'lunchService':'dinnerService'].plannedServiceId===editing.planned?.id);
 const preferred=destination.menu.days.find(d=>d.date===preferredDate);const chosen=preferred&&available(preferred,preferredPeriod||'lunch')?{date:preferred.date,period:preferredPeriod||'lunch'}:destination.menu.days.flatMap(d=>['lunch','dinner'].filter(p=>available(d,p)).map(p=>({date:d.date,period:p})))[0];
 field.value=chosen?.date||destination.menu.days[0].date;content.querySelector('[name="mealPeriod"]').value=chosen?.period||'lunch';
 }finally{if(editing.destinationRequest===requestId){editing.destinationLoading=false;if(state.editing===editing){updatePlanningRecap();editing.miniPicker?.refresh();}}}
}
function updatePlanningRecap(){const editing=state.editing;if(editing?.kind!=='planning'||!editing.destination)return;
 const day=editing.destination.menu.days.find(d=>d.date===content.querySelector('[name="date"]').value),period=content.querySelector('[name="mealPeriod"]');
 for(const option of period.options){const service=day[option.value==='lunch'?'lunchService':'dinnerService'];option.disabled=!!service&&(editing.action==='copy'||service.plannedServiceId!==editing.planned?.id);option.textContent=(option.value==='lunch'?'Midi':'Soir')+(option.disabled?' · occupé':'');}
 if(period.selectedOptions[0].disabled){const free=[...period.options].find(o=>!o.disabled);if(free)period.value=free.value;}
 const occupied=period.selectedOptions[0].disabled,name=content.querySelector('[name="serviceTemplateId"]').selectedOptions[0]?.textContent,count=content.querySelector('[name="coverCount"]').value;
 content.querySelector('.planning-recap').innerHTML=occupied?'<strong>Ce jour est complet.</strong> Choisissez un autre jour ou une autre semaine.':'<strong>'+esc(name)+'</strong><p>'+esc(day.dayLabel)+' '+shortDate(day.date)+' · '+(period.value==='lunch'?'Midi':'Soir')+' · '+esc(count)+' couverts</p>';
 form.querySelector('[type="submit"]').disabled=occupied||editing.destinationLoading||editing.selectionPending;
}
content.addEventListener('change',async event=>{if(state.editing?.kind!=='planning'||!event.target.name)return;try{if(event.target.name==='weekId')await loadPlanningDestination(event.target.value);else{if(event.target.name==='serviceTemplateId'&&state.editing.action==='add')content.querySelector('[name="coverCount"]').value=state.editing.choices.find(t=>t.id===event.target.value).referenceCovers;updatePlanningRecap();if(['date','mealPeriod'].includes(event.target.name))state.editing.miniPicker?.refresh();}}catch(error){document.getElementById('editor-error').textContent=error.message;form.querySelector('[type="submit"]').disabled=true;}});
content.addEventListener('input',event=>{if(event.target.name==='coverCount'&&state.editing?.kind==='planning')updatePlanningRecap();});



content.addEventListener('change',event=>{if(!['week','week-copy'].includes(state.editing?.kind))return;if(event.target.name==='weekYear'){const select=content.querySelector('[name="startDate"]');select.innerHTML=WeekInfo.weeksOfYear(event.target.value).map(w=>'<option value="'+w.start+'">Semaine '+w.number+' — '+esc(w.title)+'</option>').join('');}if(event.target.name==='coverMode'){content.querySelector('#copy-common').hidden=event.target.value!=='common';content.querySelector('#copy-individual').hidden=event.target.value!=='individual';}});
content.addEventListener('click',event=>{const b=event.target.closest('[data-week-shift]');if(!b)return;const select=content.querySelector('[name="startDate"]'),d=new Date(select.value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+7*Number(b.dataset.weekShift));const start=d.toISOString().slice(0,10),year=WeekInfo.weekInfo(start).year,years=content.querySelector('[name="weekYear"]');if(!Array.from(years.options).some(o=>Number(o.value)===year))years.add(new Option(year,year));years.value=year;years.dispatchEvent(new Event('change',{bubbles:true}));select.value=start;});

function refreshWeekPreview(){const select=content.querySelector('[name="startDate"]'),preview=content.querySelector('#new-week-title');if(select&&preview){const info=WeekInfo.weekInfo(select.value);preview.textContent=info.title+' · '+info.label;}}
content.addEventListener('change',()=>{if(['week','week-copy'].includes(state.editing?.kind))refreshWeekPreview();});
