document.addEventListener('click',async event=>{const button=event.target.closest('[data-permanent-kind]');if(!button)return;button.disabled=true;try{const kind=button.dataset.permanentKind,id=button.dataset.permanentId,info=await api('/api/library/deletion?'+query({kind,id}));if(!info.allowed){alert((kind==='dish'?'Ce plat est encore utilisé par ces services types : ':'Ce service type est présent dans le planning ou l’historique : ')+info.usages.map(u=>u.name||shortDate(String(u.service_date).slice(0,10))+' · '+(u.meal_period==='lunch'?'Midi':'Soir')).join('\n')+'\nAucun élément ne sera supprimé.');return;}const approved=confirm('Suppression définitive et irréversible de « '+info.name+' ».\n'+(kind==='service'?'Les plats restent dans la bibliothèque.':'La recette de ce plat sera également supprimée.')+'\nConfirmer la suppression définitive ?');if(!approved)return;await api('/api/library/permanent',{method:'DELETE',body:JSON.stringify({kind,id,expectedVersion:info.version,confirmed:true})});await render();if(kind==='dish')document.querySelector('[data-library-tab=dishes]')?.click();notify('Suppression définitive effectuée.');}catch(error){notify(error.message);}finally{button.disabled=false;}});

