dishUsagesDialog.addEventListener('close',()=>dishUsagesRequest++);
dishUsagesDialog.addEventListener('click',e=>{if(e.target.closest('[data-usages-close]'))return dishUsagesDialog.close();const button=e.target.closest('[data-action=choose-slot]');if(button){e.preventDefault();chooseSlot(button.dataset.template);}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-dish-usages]');if(!button)return;const token=++dishUsagesRequest,name=button.closest('.dish-card')?.querySelector('h3')?.textContent||'ce plat';dishUsagesDialog.innerHTML='<div class="dialog-head"><h2>Services utilisant « '+esc(name)+' »</h2><button type="button" class="button secondary" data-usages-close>Fermer</button></div><p role="status">Chargement des services…</p>';if(!dishUsagesDialog.open)dishUsagesDialog.showModal();try{const [usages,services]=await Promise.all([api('/api/dishes/usages?'+query({id:button.dataset.dishUsages})),api('/api/library?includeInactive=1')]);if(token!==dishUsagesRequest||!dishUsagesDialog.open)return;const rows=usages.map(u=>services.find(s=>s.id===u.id)).filter(Boolean);dishUsagesDialog.querySelector('[role=status]').outerHTML='<p class="muted">'+rows.length+' service'+(rows.length>1?'s':'')+' type'+(rows.length>1?'s':'')+' · Cliquez sur une carte pour ouvrir sa fiche technique.</p><section id="usage-service-cards" class="library-grid" data-library-view="small">'+rows.map(s=>{const was=showArchivedServices;showArchivedServices=s.active===false;const filter=serviceTypeFilter;serviceTypeFilter='';try{return libraryCards([s]);}finally{showArchivedServices=was;serviceTypeFilter=filter;}}).join('')+'</section>';}catch(error){const status=dishUsagesDialog.querySelector('[role=status]');if(token===dishUsagesRequest&&status)status.textContent=error.message;}});



app.addEventListener('click',event=>{const button=event.target.closest('[data-service-filter]');if(!button)return;serviceTypeFilter=button.dataset.serviceFilter;document.querySelectorAll('[data-service-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.getElementById('library-search').dispatchEvent(new Event('input',{bubbles:true}));});

document.addEventListener('click',async event=>{const button=event.target.closest('[data-service-duplicate]');if(!button||button.disabled)return;button.disabled=true;try{const source=await api('/api/library/editor?'+query({id:button.dataset.serviceDuplicate})),snapshot=source.snapshot;snapshot.service.name+=' — copie';const copy=await api('/api/assembly/duplicate',{method:'POST',body:JSON.stringify({snapshot})});await render();await openLibrary(copy.id,'edit');}catch(error){notify(error.message);}finally{button.disabled=false;}});



// Display preference stays on this browser and does not change the planning.
(()=>{
 const key='paperchef-interface-density-v2',root=document.documentElement;
 let density='standard';try{const saved=localStorage.getItem(key),previous=localStorage.getItem('paperchef-interface-density');if(['comfortable','standard','compact'].includes(saved))density=saved;else{density=previous==='standard'?'comfortable':'standard';localStorage.setItem(key,density);}}catch{}
 root.dataset.interfaceDensity=density;
 const control=document.createElement('details');control.className='interface-view-choice';
 control.innerHTML='<summary aria-label="Choisir la vue" title="Vue confortable, standard ou compacte"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M9 9v11"/></svg></summary><div class="interface-view-menu" role="group" aria-label="Taille de l\u2019interface"><button type="button" data-interface-density="comfortable">Confortable</button><button type="button" data-interface-density="standard">Standard</button><button type="button" data-interface-density="compact">Compacte</button><small>Choix conserv\u00e9 sur ce navigateur.</small></div>';
 function draw(){for(const b of control.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.interfaceDensity===density));}
 control.addEventListener('click',e=>{const b=e.target.closest('button[data-interface-density]');if(!b)return;density=b.dataset.interfaceDensity;root.dataset.interfaceDensity=density;try{localStorage.setItem(key,density);}catch{}draw();control.open=false;control.querySelector('summary').focus();});
 document.addEventListener('pointerdown',e=>{if(!control.contains(e.target))control.open=false;});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&control.open){control.open=false;control.querySelector('summary').focus();}});
 control.addEventListener('toggle',()=>{if(!control.open)return;const box=control.querySelector('summary').getBoundingClientRect();control.style.setProperty('--view-menu-top',(box.bottom+7)+'px');control.style.setProperty('--view-menu-left',Math.max(12,Math.min(box.left,innerWidth-202))+'px');});
 document.querySelector('.app-header').append(control);draw();
})();

// Local document drafts store changes, rather than full copies for every keystroke.
window.PaperChefDocumentHistory={create({kind,weekId,original,getModel,onChange}){
 const clone=x=>structuredClone(x),replace=(target,value)=>{for(const key of Object.keys(target))delete target[key];Object.assign(target,clone(value));};
 let hash=2166136261;for(const c of JSON.stringify(original)){hash^=c.charCodeAt(0);hash=Math.imul(hash,16777619);}
 const key='paperchef:document-draft:'+JSON.stringify([window.PaperChefShared?.user?.id||'local',kind,weekId,hash>>>0]);
 let undo=[],redo=[],last,groupBase=null,groupTag='',groupTime=0,storageNotice=false;
 try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.version===1&&saved.model){replace(getModel(),saved.model);undo=saved.undo||[];redo=saved.redo||[];}}catch{}
 last=clone(getModel());
 function difference(a,b,path=[],out=[]){if(JSON.stringify(a)===JSON.stringify(b))return out;if(a&&b&&typeof a==='object'&&typeof b==='object'&&Array.isArray(a)===Array.isArray(b)&&(!Array.isArray(a)||a.length===b.length)){for(const key of new Set([...Object.keys(a),...Object.keys(b)]))difference(a[key],b[key],[...path,key],out);}else out.push({path,before:clone(a),after:clone(b),hasBefore:a!==undefined,hasAfter:b!==undefined});return out;}
 function persist(){const payload=()=>JSON.stringify({version:1,model:getModel(),undo,redo});try{localStorage.setItem(key,payload());}catch{try{localStorage.setItem(key,JSON.stringify({version:1,model:getModel(),undo:[],redo:[]}));}catch{if(!storageNotice&&typeof notify==='function'){storageNotice=true;notify('Le navigateur ne peut pas enregistrer ces retouches. Gardez l’éditeur ouvert et téléchargez votre PDF.');}}}}
 function changed(){last=clone(getModel());persist();onChange?.();}
 function apply(patches,direction){for(const p of patches){let target=getModel();for(const part of p.path.slice(0,-1))target=target[part];const end=p.path.at(-1);if(!p.path.length)replace(target,p[direction]);else if(p[direction==='before'?'hasBefore':'hasAfter'])target[end]=clone(p[direction]);else delete target[end];}}
 const api={commit(tag=''){const current=getModel(),patches=difference(last,current);if(!patches.length)return;const now=Date.now();if(tag&&tag===groupTag&&now-groupTime<900&&groupBase&&undo.length){undo[undo.length-1]=difference(groupBase,current);}else{groupBase=clone(last);undo.push(patches);if(undo.length>60)undo.shift();}redo=[];groupTag=tag;groupTime=now;changed();},undo(){if(!undo.length)return;const patches=undo.pop();apply(patches,'before');redo.push(patches);groupTag='';groupBase=null;changed();},redo(){if(!redo.length)return;const patches=redo.pop();apply(patches,'after');undo.push(patches);groupTag='';groupBase=null;changed();},reset(){replace(getModel(),original);api.commit();},canUndo:()=>undo.length>0,canRedo:()=>redo.length>0,save:persist};return api;
}};
